 * elsewhere must still refuse to let it override a mechanical disagreement.
 */
export function judgeVerifySemanticCorrectness(proposedVerify) {
  if (matchesKnownBadVerifyPattern(proposedVerify)) {
    return {
      agrees: false,
      mechanical: true,
